insert into public.materials (id,topic_id,title,introduction,status) values ('00000000-0000-4000-8000-000000010002','7b5e6723-9d87-46dd-9e2e-4e00d1ec05eb','Desenvolvimento e aprendizagem','Neste tópico você vai compreender por que desenvolvimento e aprendizagem não são conceitos intercambiáveis e como Piaget e Vygotsky ajudam a analisar essa relação. Ao final, você deverá comparar perspectivas sem reduzi-las a slogans, interpretar situações educativas e reconhecer o papel da ação, da mediação e do contexto.','published') on conflict (id) do nothing;
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010003','00000000-0000-4000-8000-000000010002','O que significa desenvolver','Desenvolvimento pode ser entendido como um processo de transformação das formas de agir, pensar, relacionar-se e participar do mundo. Em Psicologia da Educação, é importante evitar a ideia de que aprender seja apenas receber informações. As formas como a pessoa age, interpreta situações e participa de relações também se transformam. A pergunta central para estudar é: “O que mudou na forma de pensar ou agir e que condições contribuíram para essa mudança?”',1,'concept');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010004','00000000-0000-4000-8000-000000010002','Desenvolvimento e aprendizagem não são a mesma coisa','Aprendizagem e desenvolvimento estão relacionados, mas as teorias não os explicam do mesmo modo. Uma abordagem pode enfatizar a construção realizada pelo sujeito em interação com situações e objetos; outra pode destacar que processos de aprendizagem mediados socialmente participam do desenvolvimento. Por isso, em uma questão de prova, observe qual teoria está sendo usada antes de concluir que uma afirmação vale para todas as perspectivas.',2,'explanation');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010005','00000000-0000-4000-8000-000000010002','A perspectiva de Piaget','Na teoria de Piaget, o sujeito constrói conhecimentos por meio de sua atividade e de coordenações progressivas de ações. O contato com situações que não se ajustam plenamente ao que já se sabe pode produzir desequilíbrios e exigir reconstruções. Isso não significa que o professor apenas “deixe a criança descobrir”; significa organizar situações em que o aluno possa agir, comparar, explicar e reconstruir suas ideias.',3,'deepening');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010006','00000000-0000-4000-8000-000000010002','A perspectiva de Vygotsky','Na perspectiva histórico-cultural associada a Vygotsky, o desenvolvimento humano é compreendido em relação à cultura, à linguagem e às relações sociais. A aprendizagem mediada por outras pessoas e por instrumentos culturais tem papel importante nesse processo. Para estudar, conecte três ideias: participação social, mediação e apropriação de conhecimentos culturalmente produzidos.',4,'examples');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010007','00000000-0000-4000-8000-000000010002','Como analisar uma situação educativa','Imagine um aluno que resolve um problema usando uma estratégia inicial e, depois de discutir com colegas e professor, reorganiza seu modo de pensar. A situação pode ser analisada por diferentes teorias, mas cada uma fará perguntas específicas. Em prova, não basta reconhecer o nome do autor; é preciso identificar o mecanismo teórico destacado no enunciado.',5,'common_mistakes');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010008','00000000-0000-4000-8000-000000010002','Revisão rápida','Guarde estas ideias: desenvolvimento envolve transformações; aprendizagem e desenvolvimento são relacionados, mas não idênticos; Piaget enfatiza a atividade e a construção do conhecimento; Vygotsky destaca mediação social, linguagem e cultura. Para revisar, compare uma situação de aprendizagem individual com uma situação em que a interação social modifica o percurso e explique como cada perspectiva a interpretaria.',6,'review');
