insert into public.materials (id,topic_id,title,introduction,status) values ('00000000-0000-4000-8000-000000010078','7b8f766f-dc23-44ce-8b44-7fc5c0135ddd','Construtivismo e construção do conhecimento','Neste tópico você vai compreender o construtivismo como uma perspectiva sobre a construção do conhecimento, e não como uma receita de aula. Ao final, você deverá reconhecer o papel da atividade do sujeito, do conflito cognitivo, da interação e da reconstrução das ideias, distinguindo essas noções de interpretações simplificadas.','published') on conflict (id) do nothing;
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010079','00000000-0000-4000-8000-000000010078','Conhecimento como construção','Em uma perspectiva construtivista, o estudante não é visto como recipiente vazio. O conhecimento é construído por meio da atividade do sujeito diante de problemas, objetos e situações. Isso não significa que qualquer ideia esteja correta ou que o ensino seja dispensável. Significa que aprender envolve reorganizar modos de compreender, em vez de apenas acumular respostas.',1,'concept');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010080','00000000-0000-4000-8000-000000010078','Esquemas e reorganização','O sujeito interpreta situações com base em conhecimentos que já possui. Quando uma nova situação não se ajusta ao que ele consegue explicar, pode ser necessário reorganizar suas formas de pensar. Esse movimento ajuda a entender por que respostas erradas podem ser pistas importantes sobre o raciocínio do aluno e não apenas sinais de fracasso.',2,'explanation');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010081','00000000-0000-4000-8000-000000010078','Desequilíbrio e reconstrução','Uma situação de desequilíbrio pode ocorrer quando aquilo que o estudante prevê não coincide com o resultado observado. O objetivo pedagógico não é provocar confusão por si só, mas criar situações que desafiem ideias existentes de forma produtiva. Depois do desafio, é preciso espaço para comparar, argumentar e reconstruir explicações.',3,'deepening');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010082','00000000-0000-4000-8000-000000010078','Interação e socioconstrutivismo','Abordagens socioconstrutivistas dão maior destaque à construção mediada socialmente. A discussão com colegas, a linguagem e a intervenção de outros participantes podem modificar o modo como o estudante coordena suas ações e interpreta um problema. Interação, portanto, não é simplesmente “trabalhar em grupo”; é uma condição que pode produzir novas formas de compreender.',4,'examples');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010083','00000000-0000-4000-8000-000000010078','O que construtivismo não significa','Não significa abandonar o ensino, deixar o aluno sozinho ou considerar que todo conhecimento escolar surgirá espontaneamente. Também não significa que o professor não possa ensinar conceitos, fazer perguntas, oferecer informações e organizar percursos. A diferença está em compreender o estudante como participante da construção do conhecimento.',5,'common_mistakes');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010084','00000000-0000-4000-8000-000000010078','Revisão rápida','Para revisar: o aluno participa ativamente da construção; conhecimentos anteriores orientam novas interpretações; desafios podem exigir reorganização; interação e linguagem podem participar da construção; ensino e atividade do aluno podem coexistir. Antes da prova, explique por que “construtivismo = deixar descobrir sozinho” é uma simplificação inadequada.',6,'review');
