insert into public.materials (id,topic_id,title,introduction,status) values ('00000000-0000-4000-8000-000000010154','60592ad9-932f-41cb-afba-1b022b8cdecb','Psicologia histórico-cultural e mediação','Neste tópico você vai estudar a perspectiva histórico-cultural e compreender como cultura, linguagem, atividade e mediação ajudam a explicar a aprendizagem e o desenvolvimento. Ao final, você deverá analisar o papel das relações sociais e reconhecer por que a educação pode participar da apropriação de conhecimentos culturalmente produzidos.','published') on conflict (id) do nothing;
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010155','00000000-0000-4000-8000-000000010154','O ser humano em contexto histórico-cultural','A perspectiva histórico-cultural entende o desenvolvimento humano em relação às condições sociais e culturais. O sujeito participa de um mundo produzido historicamente e se apropria de conhecimentos, práticas e significados construídos socialmente. Isso desloca a análise de uma explicação baseada apenas em características internas do indivíduo.',1,'concept');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010156','00000000-0000-4000-8000-000000010154','Cultura e apropriação','A cultura não aparece apenas como cenário externo. Ela inclui conhecimentos, linguagens, ferramentas, práticas e formas de organização da atividade. Aprender envolve apropriar-se dessas produções, transformando a maneira de agir e compreender. Na escola, isso destaca a importância do acesso sistemático ao conhecimento e da participação em práticas orientadas.',2,'explanation');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010157','00000000-0000-4000-8000-000000010154','Mediação','Mediação é uma ideia central para compreender como relações, linguagem e instrumentos participam da atividade humana. Em vez de imaginar um contato direto e isolado entre pessoa e mundo, a análise considera os meios culturais e sociais envolvidos. Para estudar, pergunte: “O que ou quem está mediando a atividade e que possibilidade de ação isso cria?”',3,'deepening');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010158','00000000-0000-4000-8000-000000010154','Linguagem e interação','A linguagem participa da comunicação e também da organização das formas de pensar e agir. Em uma atividade escolar, conversar sobre um problema, ouvir explicações, nomear estratégias e registrar raciocínios pode modificar o modo como o aluno enfrenta a tarefa. A interação, portanto, pode ser parte constitutiva do processo de aprendizagem.',4,'examples');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010159','00000000-0000-4000-8000-000000010154','O papel da escola','A escola pode organizar experiências de acesso a conhecimentos que não surgem automaticamente da vida cotidiana. Isso exige intencionalidade, mediação e planejamento. Um erro comum é interpretar a perspectiva histórico-cultural como defesa de espontaneidade absoluta; a ênfase está justamente nas condições sociais e educativas que podem favorecer o desenvolvimento.',5,'common_mistakes');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010160','00000000-0000-4000-8000-000000010154','Revisão rápida','Guarde: desenvolvimento é histórico e culturalmente situado; cultura é parte constitutiva da atividade humana; mediação conecta sujeito, mundo e instrumentos culturais; linguagem participa da interação e da organização do pensamento; educação pode favorecer apropriação de conhecimentos. Revise explicando a diferença entre “aprender sozinho” e “aprender em atividade mediada”.',6,'review');
