insert into public.materials (id,topic_id,title,introduction,status) values ('00000000-0000-4000-8000-000000010230','b95907ea-b1bf-44f9-8a63-744dc9584248','Interação, afetividade e práticas educativas','Neste tópico você vai analisar como interação e afetividade aparecem nas relações educativas sem reduzir a aprendizagem a emoções isoladas. Ao final, você deverá reconhecer a dimensão afetiva das relações pedagógicas, compreender sua articulação com aspectos cognitivos e interpretar situações de sala de aula com mais precisão.','published') on conflict (id) do nothing;
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010231','00000000-0000-4000-8000-000000010230','Afetividade também faz parte da relação educativa','A relação educativa envolve dimensões cognitivas, sociais e afetivas. Isso não significa que sentir algo determine automaticamente a aprendizagem. Significa reconhecer que confiança, segurança, vínculo, expectativas e formas de participação fazem parte das condições em que o estudante aprende. A análise pedagógica melhora quando considera essas dimensões em conjunto.',1,'concept');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010232','00000000-0000-4000-8000-000000010230','Interação professor-aluno','A interação professor-aluno envolve comunicação, expectativas, feedback, escuta e formas de organizar a participação. Uma intervenção pode influenciar não só o conteúdo aprendido, mas também a disposição do aluno para participar e persistir. Por isso, a relação pedagógica não é um elemento separado da atividade de ensino.',2,'explanation');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010233','00000000-0000-4000-8000-000000010230','Afeto e cognição não competem','É inadequado tratar aspectos afetivos e cognitivos como concorrentes: “ou trabalhamos conteúdo ou cuidamos da relação”. A pesquisa educacional pode discutir como essas dimensões se articulam. O professor pode manter altas expectativas acadêmicas e, ao mesmo tempo, construir relações respeitosas e condições de participação.',3,'deepening');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010234','00000000-0000-4000-8000-000000010230','Exemplo de prática educativa','Imagine uma turma em que alguns alunos deixam de participar por receio de errar. O professor passa a usar perguntas graduadas, valoriza justificativas, cria oportunidades de revisão e dá feedback específico. A intervenção não é apenas “emocional”: ela altera a própria organização da aprendizagem e pode ampliar a participação cognitiva dos estudantes.',4,'examples');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010235','00000000-0000-4000-8000-000000010230','Erros comuns','Um erro é transformar afetividade em elogio permanente ou pensar que uma relação acolhedora substitui conhecimento e planejamento. Outro é ignorar a dimensão afetiva e tratar o aluno apenas como desempenho. Em prova, procure alternativas que integrem respeito, interação, expectativas acadêmicas, mediação e aprendizagem.',5,'common_mistakes');
insert into public.material_sections (id,material_id,title,content,position,section_type) values ('00000000-0000-4000-8000-000000010236','00000000-0000-4000-8000-000000010230','Revisão rápida','Revise: relações educativas têm dimensão cognitiva e afetiva; interação influencia participação; afeto não substitui conteúdo; feedback e expectativas fazem parte da relação pedagógica; práticas educativas precisam integrar aprendizagem e condições de participação. Para revisar, explique por que “afeto é só elogiar” e “afeto não tem relação com aprendizagem” são duas simplificações diferentes.',6,'review');
insert into public.topic_sources (topic_id,source_id,role,status) values ('b95907ea-b1bf-44f9-8a63-744dc9584248','8e7f9e18-4c9e-4e37-ae2f-7a2c5fcde101','BASE','APPROVED') on conflict do nothing;
